import java.util.*;

class Solution {
  public int videoStitching(int[][] clips, int time) {
    Arrays.sort(
        clips, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(b[1], a[1]));
    int used = 0, currentEnd = 0, nextEnd = 0, index = 0;
    while (currentEnd < time) {
      while (index < clips.length && clips[index][0] <= currentEnd) {
        nextEnd = Math.max(nextEnd, clips[index][1]);
        index++;
      }
      if (nextEnd == currentEnd) return -1;
      used++;
      currentEnd = nextEnd;
    }
    return used;
  }
}
